namespace RecipeShare.Models;

public class RecipeCategory
{
    public string Name { get; set; } = "";
    public string Slug { get; set; } = "";
    public string Description { get; set; } = "";
    public string Icon { get; set; } = "";
}

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CategorySlug { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories = new()
    {
        new() { Name = "Breakfast", Slug = "breakfast", Description = "Start your day right", Icon = "🍳" },
        new() { Name = "Lunch", Slug = "lunch", Description = "Midday meals and light bites", Icon = "🥗" },
        new() { Name = "Dinner", Slug = "dinner", Description = "Hearty evening dishes", Icon = "🍝" },
        new() { Name = "Desserts", Slug = "desserts", Description = "Sweet treats and baked goods", Icon = "🍰" },
        new() { Name = "Snacks", Slug = "snacks", Description = "Quick bites between meals", Icon = "🥨" },
        new() { Name = "Drinks", Slug = "drinks", Description = "Beverages and smoothies", Icon = "🥤" },
    };

    private readonly List<Recipe> _recipes = new()
    {
        new()
        {
            Id = 1, Title = "Classic Pancakes", CategorySlug = "breakfast",
            Ingredients = new() { "2 cups flour", "2 eggs", "1.5 cups milk", "2 tbsp sugar", "1 tsp baking powder", "Pinch of salt" },
            Steps = new() { "Mix dry ingredients together.", "Whisk eggs and milk, then combine with dry mix.", "Heat a buttered pan over medium heat.", "Pour batter and cook until bubbles form, then flip.", "Serve with maple syrup and fresh berries." },
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", CategorySlug = "breakfast",
            Ingredients = new() { "2 slices sourdough bread", "1 ripe avocado", "Salt and pepper", "Red pepper flakes", "1 tbsp lemon juice" },
            Steps = new() { "Toast the bread until golden.", "Mash avocado with lemon juice, salt, and pepper.", "Spread onto toast.", "Top with red pepper flakes." },
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", CategorySlug = "lunch",
            Ingredients = new() { "1 head romaine lettuce", "1/2 cup croutons", "1/4 cup parmesan", "Caesar dressing", "Grilled chicken (optional)" },
            Steps = new() { "Wash and chop romaine lettuce.", "Toss with Caesar dressing.", "Top with croutons and shaved parmesan.", "Add grilled chicken if desired." },
            AverageRating = 4.0, RatingCount = 6
        },
        new()
        {
            Id = 4, Title = "Spaghetti Bolognese", CategorySlug = "dinner",
            Ingredients = new() { "400g spaghetti", "500g ground beef", "1 can crushed tomatoes", "1 onion, diced", "3 cloves garlic", "Fresh basil", "Olive oil" },
            Steps = new() { "Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil.", "Add ground beef and brown.", "Stir in crushed tomatoes and simmer 20 minutes.", "Serve sauce over pasta, garnish with basil." },
            AverageRating = 4.8, RatingCount = 20
        },
        new()
        {
            Id = 5, Title = "Chocolate Chip Cookies", CategorySlug = "desserts",
            Ingredients = new() { "2.25 cups flour", "1 cup butter, softened", "3/4 cup sugar", "2 eggs", "1 tsp vanilla", "2 cups chocolate chips", "1 tsp baking soda" },
            Steps = new() { "Preheat oven to 375°F (190°C).", "Cream butter and sugar together.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheet.", "Bake 9-11 minutes until golden." },
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 6, Title = "Trail Mix", CategorySlug = "snacks",
            Ingredients = new() { "1 cup almonds", "1 cup cashews", "1/2 cup dried cranberries", "1/2 cup dark chocolate chips", "1/4 cup sunflower seeds" },
            Steps = new() { "Combine all ingredients in a large bowl.", "Toss to mix evenly.", "Store in an airtight container." },
            AverageRating = 3.8, RatingCount = 4
        },
        new()
        {
            Id = 7, Title = "Berry Smoothie", CategorySlug = "drinks",
            Ingredients = new() { "1 cup mixed berries", "1 banana", "1 cup yogurt", "1/2 cup orange juice", "1 tbsp honey" },
            Steps = new() { "Add all ingredients to a blender.", "Blend until smooth.", "Pour into a glass and serve immediately." },
            AverageRating = 4.3, RatingCount = 10
        },
    };

    private int _nextId = 8;
    private readonly Lock _lock = new();

    public List<RecipeCategory> GetCategories() => _categories;

    public RecipeCategory? GetCategory(string slug) =>
        _categories.FirstOrDefault(c => c.Slug == slug);

    public List<Recipe> GetRecipesByCategory(string categorySlug) =>
        _recipes.Where(r => r.CategorySlug == categorySlug).ToList();

    public Recipe? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is null) return;

            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }
}

@page "/category/{Slug}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(category?.Name ?? "Category") - RecipeShare</PageTitle>

@if (category is null)
{
    <h1>Category not found</h1>
    <p><a href="/">Back to Home</a></p>
}
else
{
    <h1>@category.Icon @category.Name</h1>
    <p class="lead">@category.Description</p>

    var recipes = RecipeService.GetRecipesByCategory(Slug);

    @if (recipes.Count == 0)
    {
        <p>No recipes in this category yet. <a href="submit">Be the first to submit one!</a></p>
    }
    else
    {
        <div class="row mt-3">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                                <small class="text-muted">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</small>
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }

    <a href="/" class="btn btn-link mt-3">← Back to Categories</a>
}

@code {
    [Parameter]
    public string Slug { get; set; } = "";

    private RecipeCategory? category;

    protected override void OnInitialized()
    {
        category = RecipeService.GetCategory(Slug);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <p><a href="/">Back to Home</a></p>
}
else
{
    <h1>@recipe.Title</h1>

    <div class="mb-4">
        <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Ingredients</h4></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>Instructions</h4>
            <ol class="list-group list-group-numbered mt-2">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <a href="category/@recipe.CategorySlug" class="btn btn-link mt-4">← Back to Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    <span>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button"
                  style="font-size: 1.5rem; cursor: pointer; color: @(star <= (hoveredStar ?? selectedStar) ? "#ffc107" : "#dee2e6");"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = null">★</span>
        }
    </span>
    <span class="text-muted small">
        @if (submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        else
        {
            @($"{CurrentRating:F1} / 5 ({RatingCount} ratings) — click to rate")
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int? hoveredStar;
    private int selectedStar;
    private bool submitted;

    private void Rate(int stars)
    {
        if (submitted) return;
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label class="form-label" for="title">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="category">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="model.CategorySlug">
            <option value="">-- Select a category --</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat.Slug">@cat.Name</option>
            }
        </InputSelect>
        <ValidationMessage For="() => model.CategorySlug" class="text-danger" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="model.IngredientsText" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => model.IngredientsText" class="text-danger" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.StepsText" placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;..." />
        <ValidationMessage For="() => model.StepsText" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
    <a href="/" class="btn btn-link">Cancel</a>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            CategorySlug = model.CategorySlug,
            Ingredients = model.IngredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = model.StepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
        };

        RecipeService.AddRecipe(recipe);
        successMessage = $"'{recipe.Title}' submitted successfully! View it in the {model.CategorySlug} category.";
        model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100)]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string CategorySlug { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one ingredient.")]
        public string IngredientsText { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one step.")]
        public string StepsText { get; set; } = "";
    }
}

