toolArgs.file_text:
@page "/category/{Slug}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(category?.Name ?? "Category") - RecipeShare</PageTitle>

@if (category is null)
{
    <h1>Category not found</h1>
    <p><a href="/">Back to Home</a></p>
}
else
{
    <h1>@category.Icon @category.Name</h1>
    <p class="lead">@category.Description</p>

    var recipes = RecipeService.GetRecipesByCategory(Slug);

    @if (recipes.Count == 0)
    {
        <p>No recipes in this category yet. <a href="submit">Be the first to submit one!</a></p>
    }
    else
    {
        <div class="row mt-3">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                                <small class="text-muted">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</small>
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }

    <a href="/" class="btn btn-link mt-3">← Back to Categories</a>
}

@code {
    [Parameter]
    public string Slug { get; set; } = "";

    private RecipeCategory? category;

    protected override void OnInitialized()
    {
        category = RecipeService.GetCategory(Slug);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <p><a href="/">Back to Home</a></p>
}
else
{
    <h1>@recipe.Title</h1>

    <div class="mb-4">
        <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Ingredients</h4></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>Instructions</h4>
            <ol class="list-group list-group-numbered mt-2">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <a href="category/@recipe.CategorySlug" class="btn btn-link mt-4">← Back to Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    <span>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button"
                  style="font-size: 1.5rem; cursor: pointer; color: @(star <= (hoveredStar ?? selectedStar) ? "#ffc107" : "#dee2e6");"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = null">★</span>
        }
    </span>
    <span class="text-muted small">
        @if (submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        else
        {
            @($"{CurrentRating:F1} / 5 ({RatingCount} ratings) — click to rate")
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int? hoveredStar;
    private int selectedStar;
    private bool submitted;

    private void Rate(int stars)
    {
        if (submitted) return;
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

